94	<MenuMovil />
95	<script>
96	  import { Icon } from "lucide-react";
97	
98	  document.addEventListener("DOMContentLoaded", () => {
99	    const IconMenu = document.getElementById("IconMenu");
100	    const navbarMovil = document.querySelector(".navbarMovil");
101	    const menuMovil = document.querySelector(".menuMovil");
102	    const menuMovilBack = document.querySelector(".menuMovilBack");
103	    const btnIconMenu = document.getElementById("btnIconMenu");
104	    const navbar = document.querySelector(".navbar");
105	    const navbarMenu = document.querySelector(".navbar-menu");
106	
107	    if (!navbar) return;
108	
109	    const handle = (scrollTop) => {
110	      if (scrollTop > 100) {
111	        navbar.classList.add("inMoved");
112	        navbarMenu.classList.add("inMoved");
113	      } else {
114	        navbar.classList.remove("inMoved");
115	        navbarMenu.classList.remove("inMoved");
116	      }
117	    };
118	
119	    const onWin = () => handle(window.scrollY || window.pageYOffset || 0);
120	    const onEl = (e) => handle(e.target.scrollTop ?? 0);
121	
122	    // Attach to common scroll targets to cover cases where scroll happened
123	    // on an element instead of the window (e.g. custom wrappers).
124	    window.addEventListener("scroll", onWin, { passive: true });
125	    document.addEventListener("scroll", onEl, { passive: true });
126	    document.addEventListener("click", (event) => {
127	      if (event.target === btnIconMenu) {
128	        menuMovil?.classList.add("visibleMenu");
129	        menuMovilBack?.classList.add("visibleMenu");
130	        navbarMovil?.classList.add("hiddenMenu");
131	      }
132	      if (event.target.closest(".movil-a")) {
133	        menuMovil?.classList.remove("visibleMenu");
134	        menuMovilBack?.classList.remove("visibleMenu");
135	        navbarMovil?.classList.remove("hiddenMenu");
136	      }
137	    });
138	    // Also try specific likely containers
139	    const candidates = [
140	      document.scrollingElement,
141	      document.documentElement,
142	      document.body,
143	      document.getElementById("home"),
144	    ];
145	    for (const c of candidates) {
146	      if (!c || c === window) continue;
147	      try {
148	        c.addEventListener &&
149	          c.addEventListener("scroll", onEl, { passive: true });
150	      } catch (err) {}
151	    }
152	
153	    // initial check
154	    onWin();
155	  });
156	</script>
