1	export function hexToRgb(hex: string) {
2	  if (!hex) return { r: 255, g: 255, b: 255 };
3	  const clean = hex.replace("#", "");
4	  const full =
5	    clean.length === 3
6	      ? clean
7	          .split("")
8	          .map((c) => c + c)
9	          .join("")
10	      : clean;
11	  const int = parseInt(full, 16);
12	  return {
13	    r: (int >> 16) & 255,
14	    g: (int >> 8) & 255,
15	    b: int & 255,
16	  };
17	}
18	
19	export function hexToRgba(hex: string, alpha = 0.18) {
20	  const { r, g, b } = hexToRgb(hex);
21	  return `rgba(${r}, ${g}, ${b}, ${alpha})`;
22	}
23	
24	export function hexToShadow(hex: string, alpha = 0.18) {
25	  return hexToRgba(hex, alpha);
26	}
27	
28	export function hexToBorder(hex: string, alpha = 0.1) {
29	  return hexToRgba(hex, alpha);
30	}
