36	<script>
37	  const TOTAL_COLS = 6;
38	  const grid = document.querySelector(".skills-grid")!;
39	  const cards = grid.querySelectorAll<HTMLElement>("[data-skill]");
40	
41	  function getColStart(card: HTMLElement): number {
42	    const gridRect = grid.getBoundingClientRect();
43	    const cardRect = card.getBoundingClientRect();
44	    const colWidth = gridRect.width / TOTAL_COLS;
45	    return Math.floor((cardRect.left - gridRect.left) / colWidth) + 1;
46	  }
47	
48	  function activate(card: HTMLElement) {
49	    const colStart = getColStart(card);
50	
51	    if (colStart + 1 > TOTAL_COLS) {
52	      card.style.gridColumnStart = String(TOTAL_COLS - 1);
53	    }
54	
55	    // 👇 Congela el grid para que no reordene nada
56	    grid.classList.remove("grid-flow-dense");
57	
58	    cards.forEach((c) => {
59	      if (c !== card) {
60	        c.classList.add("opacity-20", "scale-95");
61	      }
62	    });
63	
64	    card.classList.add("!col-span-2", "!row-span-2", "is-active");
65	  }
66	
67	  function deactivate() {
68	    cards.forEach((c) => {
69	      c.style.gridColumnStart = "";
70	      c.classList.remove(
71	        "opacity-20",
72	        "scale-95",
73	        "pointer-events-none",
74	        "!col-span-2",
75	        "!row-span-2",
76	        "is-active",
77	      );
78	    });
79	
80	    // 👇 Restaura el dense al salir
81	    grid.classList.add("grid-flow-dense");
82	  }
83	
84	  grid.addEventListener("mouseover", (e) => {
85	    const card = (e.target as HTMLElement).closest<HTMLElement>("[data-skill]");
86	    if (!card) return;
87	    if (grid.querySelector(".is-active") === card) return;
88	    deactivate();
89	    activate(card);
90	  });
91	
92	  grid.addEventListener("mouseleave", () => {
93	    deactivate();
94	  });
95	</script>
